function parseMaybeJson(value) {
  if (!value) return value
  if (typeof value === 'string') {
    try { return JSON.parse(value) } catch (e) { return value }
  }
  return value
}
function checkoutPayloadFromInvoke(invoke) {
  const err = invoke?.error
  if (err) {
    const message = err?.message || err?.context?.json?.message || err?.context?.body?.message || 'Checkout request failed'
    return { error: message }
  }
  const result = parseMaybeJson(invoke?.result) || {}
  const candidates = [result, result?.data, result?.body, result?.response, parseMaybeJson(result?.body), parseMaybeJson(result?.data)]
  for (const layer of candidates) {
    if (!layer || typeof layer !== 'object') continue
    const payload = parseMaybeJson(layer)
    if (payload?.error && !payload?.url) {
      const message = payload?.message || (typeof payload.error === 'string' ? payload.error : payload.error?.message) || 'Checkout failed'
      return { error: message }
    }
    const url = payload?.url || layer?.url
    if (typeof url === 'string' && url.indexOf('http') === 0) return { url }
  }
  return { error: 'Stripe did not return a checkout URL' }
}
const front = wwLib.getFrontWindow()
const parsed = checkoutPayloadFromInvoke(context.workflow['INVOKE'])
if (parsed.error) {
  if (front && front.alert) front.alert(parsed.error)
  return { error: parsed.error }
}
try {
